import{_ as r,o,a as e,d as t}from"./chunks/framework.MWxrmMMs.js";const p=JSON.parse('{"title":"Моды","description":"Моды в Stuzhik: каталог Modrinth и CurseForge, зависимости только того, что ставите, «Не для этой сборки», граф с действиями, «Пересечения» (конфликты mixin и рецептов), закрепление версий и автообновление.","frontmatter":{"description":"Моды в Stuzhik: каталог Modrinth и CurseForge, зависимости только того, что ставите, «Не для этой сборки», граф с действиями, «Пересечения» (конфликты mixin и рецептов), закрепление версий и автообновление.","head":[["meta",{"name":"keywords","content":"minecraft моды, stuzhik, стужик, установка модов, modrinth, curseforge, forge моды, fabric моды, конфликты модов, зависимости модов, конфликт рецептов, mixin конфликт"}]]},"headers":[],"relativePath":"guide/mods.md","filePath":"guide/mods.md"}'),n={name:"guide/mods.md"};function i(s,a,l,d,h,c){return o(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="моды" tabindex="-1">Моды <a class="header-anchor" href="#моды" aria-label="Permalink to &quot;Моды&quot;">​</a></h1><p>Моды сборки живут на вкладке «Моды» страницы сборки. Сверху два режима: «Установленные» и «Каталог».</p><h2 id="каталог" tabindex="-1">Каталог <a class="header-anchor" href="#каталог" aria-label="Permalink to &quot;Каталог&quot;">​</a></h2><p>Поиск по Modrinth и CurseForge сразу под версию игры и загрузчик сборки; «Показать несовместимые» снимает этот фильтр. «Категории» сужают поиск, «В избранное» откладывает мод на потом. Список или плитки выбираются кнопкой в панели каталога и запоминаются для всех каталогов.</p><p>«Установить» берёт версию под сборку: ту, что встанет рядом с уже установленными модами. Пока мод ставится, на его карточке видно «Подбор версии…» и «Скачивание · N%», крестик «Отменить установку» останавливает. Всё, что ставится в сборку, видно и во вкладке «Установленные»: блоком «Устанавливаются» над списком.</p><p>Вместе с модом ставятся <strong>только его зависимости</strong>. Недостающие зависимости модов, которые вы не трогали, ставятся отдельно, кнопкой «Установить все недостающие» во вкладке «Зависимости».</p><p>Свой <code>.jar</code> можно перетащить в окно или добавить кнопкой «Добавить локальный мод (.jar файл)».</p><h2 id="карточка-мода" tabindex="-1">Карточка мода <a class="header-anchor" href="#карточка-мода" aria-label="Permalink to &quot;Карточка мода&quot;">​</a></h2><p>Клик по моду открывает его карточку: описание, все версии и зависимости.</p><ul><li><strong>Смена версии</strong>: выбираете версию прямо в списке, удалять и ставить заново не нужно. «Скрыть несовместимые» убирает версии, которые не подойдут к этой игре и загрузчику</li><li><strong>Граф</strong>: что от чего зависит и что с чем конфликтует</li></ul><h2 id="список-модов" tabindex="-1">Список модов <a class="header-anchor" href="#список-модов" aria-label="Permalink to &quot;Список модов&quot;">​</a></h2><ul><li><strong>Включить и выключить</strong>: переключатель в строке; выключенный мод лежит как <code>.jar.disabled</code> и не загружается</li><li><strong>Обновления</strong>: кнопка над списком проверяет новые версии для этой сборки и показывает, что обновится. Если скачать не удалось, старый файл остаётся на месте</li><li><strong>Закрепить версию</strong>: булавка в строке или пункт меню по правому клику. Обновления, автообновление и обновление модпака закреплённую версию не трогают</li><li><strong>Автообновление</strong>: значок в строке мода: найденное обновление ставится само при проверке обновлений. Будут ли его получать новые моды, решает «Настройки → Моды»</li><li><strong>Удалить</strong>: в меню мода; несколько модов можно выделить и удалить разом. Перед удалением видно, что от него зависит</li></ul><p>Изменения видны сразу, где бы они ни случились: мод, выключенный в анализе логов, обновлённый модпаком или положенный файлом в папку, появляется в списке без перезагрузки.</p><h2 id="mod-conflicts" tabindex="-1">Зависимости и конфликты <a class="header-anchor" href="#mod-conflicts" aria-label="Permalink to &quot;Зависимости и конфликты {#mod-conflicts}&quot;">​</a></h2><p>Вкладка «Зависимости» собирает всё, что мешает сборке:</p><ul><li><strong>Недостающие зависимости</strong> и <strong>не те версии</strong>: «Установить все недостающие» ставит их одной кнопкой</li><li><strong>Несовместимые пары</strong>: моды, которые вместе не работают</li><li><strong>«Не для этой сборки»</strong>: мод для другой версии игры или другого загрузчика («AppleSkin для Minecraft 1.21.11, а сборка на 1.21.1»), с кнопкой «Отключить». То же показывает проверка перед запуском</li></ul><p><strong>Граф</strong> показывает это картинкой. Из панели мода в графе его можно выключить или удалить (с тем же окном «что сломается»), а недостающую зависимость установить кнопкой рядом с ней: ставится только она и то, что нужно ей самой. Узлы остаются на своих местах.</p><h2 id="overlaps" tabindex="-1">Пересечения <a class="header-anchor" href="#overlaps" aria-label="Permalink to &quot;Пересечения {#overlaps}&quot;">​</a></h2><p>Вкладка «Пересечения» в «Зависимостях» читает jar-файлы включённых модов, ничего не запуская, и показывает, где моды наступают друг другу на ноги:</p><ul><li><strong>Конфликты миксинов</strong>: два мода заменяют один метод игры целиком или перенаправляют один вызов: одно из изменений не применится</li><li><strong>Одни и те же методы игры</strong>: несколько модов меняют один метод. Обычно это работает, но если игра падает в этом месте, начинайте с них. На Fabric и Quilt методы названы по-человечески (<code>PalettedContainer.acquire</code>, а не <code>class_2841.method_12334</code>)</li><li><strong>Один крафт, разные предметы</strong>: два мода дают на одни и те же ингредиенты разные предметы, и игра возьмёт только один рецепт. Видно сетку верстака или печи с иконками и все варианты результата. Если в сборке есть KubeJS, CraftTweaker или Polymorph, это учитывается</li><li><strong>Одинаковые материалы</strong> и <strong>руда генерируется дважды</strong>: олово, сталь, свинец от нескольких модов</li><li><strong>Библиотеки в разных версиях</strong>: моды вшивают одну библиотеку, загрузчик оставит одну</li></ul><p>«Скопировать отчёт» отдаёт всё это текстом, чтобы отправить автору мода или сборки.</p><h2 id="встроенные-проверки-обновлении" tabindex="-1">Встроенные проверки обновлений <a class="header-anchor" href="#встроенные-проверки-обновлении" aria-label="Permalink to &quot;Встроенные проверки обновлений&quot;">​</a></h2><p>Mod Menu, Iris, Distant Horizons, Forge и NeoForge умеют сами сообщать о новых версиях при каждом запуске, а Distant Horizons ещё и сам скачивать обновление. Лаунчер выключает это по умолчанию: обновлениями модов занимается он. Переключатель: «Настройки → Моды → Интеграции с модами». У одной сборки можно выбрать своё в «Редактировать», а какие сборки живут не по общей настройке, видно в «Настройки → Запуск → Свои настройки сборок».</p><h2 id="performance" tabindex="-1">Производительность <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Производительность {#performance}&quot;">​</a></h2><p>Вкладка «Производительность» (под «Ещё» на странице сборки) во время игры показывает память и процессор. С модом Spark ещё и то, сколько стоит каждый мод («Влияние»), узкие места и рекомендации. Spark ставится кнопкой там же.</p><h2 id="где-лежат-моды" tabindex="-1">Где лежат моды <a class="header-anchor" href="#где-лежат-моды" aria-label="Permalink to &quot;Где лежат моды&quot;">​</a></h2><p>В папке сборки: <code>mods</code> внутри <code>instances/&lt;сборка&gt;</code> папки данных лаунчера. Где она и как её перенести: <a href="/guide/instances.html#data-location">Сборки → Где лежат данные</a>.</p><h2 id="если-что-то-не-так" tabindex="-1">Если что-то не так <a class="header-anchor" href="#если-что-то-не-так" aria-label="Permalink to &quot;Если что-то не так&quot;">​</a></h2><p><strong>Мод не появился в игре.</strong> Посмотрите вкладку «Зависимости»: мод может быть «Не для этой сборки» (другая версия игры или загрузчик) или ему не хватает зависимости. И проверьте, что он включён.</p><p><strong>Игра упала после установки мода.</strong> <a href="/guide/log-analyzer.html">Анализатор логов</a> назовёт виновника и предложит обновить или отключить его. Прежнюю версию можно вернуть в карточке мода, в списке версий.</p><p><strong>Мод не обновляется.</strong> Версия может быть закреплена (булавка в строке) или новой версии для вашей версии игры ещё нет.</p>',31)])])}const u=r(n,[["render",i]]);export{p as __pageData,u as default};
